CHAPTERS.push({
  id: 'pkg', icon: '📥', title: 'Paket Yönetimi', sub: 'apt, dpkg, dnf, configure make install',
  missions: [
    { id: 'pk1', title: 'Listeyi tazele', xp: 15,
      story: "Paket kurmadan önce depo listesini tazelemek gerekir, apt update. Paket veritabanı root'a ait, sudo olmadan lock dosyasını açamaz ve gerçek hata mesajını görürsün. Önce sudo'suz dene, mesajı tanı.",
      task: 'apt update komutunu önce sudo olmadan, sonra sudo ile çalıştır.', hint: '`apt update` hata verir, `sudo apt update` çalışır.',
      solution: 'apt update\nsudo apt update',
      check: (sh, c) => syRan(c, /^sudo apt(-get)?\s+update/) && c.out.includes('Reading package lists') },
    { id: 'pk2', title: 'Paket ara', xp: 15,
      story: "JSON işleyen bir komut satırı aracı lazım ama adını bilmiyorsun. apt search kelime paket adı ve açıklamalarda arar, apt show paket detay verir.",
      task: 'json kelimesiyle paket ara, bulduğun paketin adını submit et.', hint: '`apt search json`.',
      solution: 'apt search json\nsubmit jq',
      check: (sh, c) => sySub(c, 'jq') },
    { id: 'pk3', title: 'htop kur', xp: 25,
      story: "top yerine renkli ve interaktif htop istiyorsun. Kurulu değil, çalıştırınca command not found. apt install root ister, sudo olmadan dpkg lock hatası gelir. Kurulumdan sonra htop çalışır, F9 kill, F7 ve F8 nice, q çıkış.",
      task: 'htop paketini kur ve çalıştır.', hint: '`sudo apt install htop` sonra `htop`.',
      solution: 'apt install htop\nsudo apt install htop\nhtop',
      check: (sh, c) => syInstalled(sh, 'htop') && syRan(c, /^htop/) && c.out.includes('Tasks:') },
    { id: 'pk4', title: 'Kurulu olanlar', xp: 15,
      story: "Denetim için kurulu paket listesi istendi. apt list --installed hepsini verir, grep ile süzersin. dpkg -l aynı bilginin düşük seviye hali.",
      task: 'Kurulu paketler arasında nginx olup olmadığını apt list ile gör.', hint: '`apt list --installed | grep nginx`.',
      solution: 'apt list --installed | grep nginx',
      check: (sh, c) => syRan(c, /apt\s+list\s+--installed|dpkg\s+-l/) && c.out.includes('nginx') },
    { id: 'pk5', title: 'Paketin dosyaları', xp: 20,
      story: "Bir paket diske neleri koyar, config dosyası nerede. dpkg -L paket kurulu paketin dosya listesini verir. Tersini de sorabilirsin, dpkg -S /yol/dosya hangi paketten geldiğini söyler.",
      task: 'curl paketinin dosyalarını listele, executable dosyanın tam yolunu submit et.', hint: '`dpkg -L curl`. /usr/bin altındaki satır.',
      solution: 'dpkg -L curl\nsubmit /usr/bin/curl',
      check: (sh, c) => sySub(c, '/usr/bin/curl') },
    { id: 'pk6', title: 'remove ve purge', xp: 20,
      story: "htop'tan vazgeçtin. apt remove paketi kaldırır ama /etc altındaki config dosyalarını bırakır, purge config dahil her şeyi siler. Temiz kaldırmak istiyorsan purge.",
      task: 'htop paketini config dosyalarıyla birlikte kaldır.', hint: '`sudo apt purge htop`. Sonra `htop` tekrar command not found.',
      solution: 'sudo apt purge htop\nhtop',
      check: sh => !syInstalled(sh, 'htop') && syHist(sh, /apt(-get)?\s+purge\s+htop/) },
    { id: 'pk7', title: 'Script için apt-get', xp: 20,
      story: "Mousepad'de apt-get yazıyor. Yanlış değil ama eski. apt insan için yapılmış modern ön yüz, ilerleme çubuğu ve renk verir. apt-get çıktısı sabit olduğu için script ve otomasyonda tercih edilir, soruları atlatmak için -y eklenir.",
      task: 'tmux paketini script usulü, apt-get ve -y ile kur.', hint: '`sudo apt-get install -y tmux`.',
      solution: 'sudo apt-get install -y tmux',
      check: (sh, c) => syInstalled(sh, 'tmux') && syRan(c, /apt-get\s+install\s+-y/) },
    { id: 'pk8', title: 'Öteki dünya', xp: 15,
      story: "Mousepad'de yum ve rpm de var. Onlar RHEL, Fedora, Rocky ve Alma ailesinin araçları, modern sürümlerde yum'un yerini dnf aldı, rpm ise dpkg'nin karşılığı. Bu kutu Ubuntu, dnf burada yok ama lab öğrenmen için gerçek çıktıyı simüle eder.",
      task: 'dnf ile htop ara, lab\'ın notunu oku.', hint: '`dnf search htop`. Sonra `rpm -qa | head` ile RHEL tarzı paket adlarına bak.',
      solution: 'dnf search htop\nrpm -qa | head -3',
      check: (sh, c) => syRan(c, /^(sudo\s+)?(dnf|yum|rpm)\b/) && c.out.includes('Debian') },
    { id: 'pk9', title: 'Kaynaktan derle', xp: 30,
      story: "Depoda olmayan bir program ~/src/hello-2.12 içinde kaynak kod olarak duruyor. Klasik üçlü, ./configure ortamı kontrol edip Makefile üretir, make derler, sudo make install sisteme kopyalar. Mousepad source komutunu bununla karıştırmış, source başka bir şey.",
      task: 'hello-2.12 dizinine gir, configure ve make çalıştır, ./hello ile programı dene.', hint: '`cd ~/src/hello-2.12`, `./configure`, `make`, `./hello`.',
      solution: 'cd ~/src/hello-2.12\n./configure\nmake\n./hello',
      check: (sh, c) => syEx(sh, SY_H + '/src/hello-2.12/hello') && c.out.includes('Hello, world!') },
    { id: 'pk10', title: 'make install', xp: 30,
      story: "Derlenen program sadece bu dizinde çalışıyor. make install onu /usr/local/bin altına kopyalar, PATH'te olduğu için her yerden hello yazarsın. /usr/local root'a ait, sudo gerekir. Sistem dizini istemiyorsan ./configure --prefix=$HOME/.local ile kendi dizinine kurarsın.",
      task: 'Programı sisteme kur ve bulunduğun dizinden bağımsız olarak hello komutunu çalıştır.', hint: '`make install` Permission denied verir, `sudo make install` sonra `hello`.',
      solution: 'cd ~/src/hello-2.12\nmake install\nsudo make install\ncd ~\nhello',
      check: (sh, c) => syEx(sh, '/usr/local/bin/hello') && syRan(c, /^hello\b/) && c.out.includes('Hello, world!') },
  ],
});

CHAPTERS.push({
  id: 'sysadm', icon: '🛠️', title: 'Sistem Yönetimi', sub: 'cal, timedatectl, modprobe, shutdown, at, ulimit, ln',
  missions: [
    { id: 'sa1', title: 'Takvim', xp: 10,
      story: "Bakım penceresi için tarih bakıyorsun. cal bu ayı gösterir, cal 2026 tüm yılı, cal 12 2026 belirli bir ayı. Terminalden çıkmadan takvime bakmak küçük ama günde on kez işe yarar.",
      task: '2026 Aralık ayını göster ve 25 Aralık\'ın hangi güne denk geldiğini İngilizce submit et.', hint: '`cal 12 2026`. Sütun başlıkları Su Mo Tu We Th Fr Sa.',
      solution: 'cal 12 2026\nsubmit Friday',
      check: (sh, c) => sySub(c, 'friday', 'fri', 'cuma') },
    { id: 'sa2', title: 'Adresler', xp: 15,
      story: "Monitoring ekibi bu kutunun tüm IP adreslerini ve FQDN'ini istiyor. hostname -I büyük i tüm adresleri verir, hostname -f tam alan adını. Mousepad'de hostname -l yazıyor, öyle bir seçenek yok, lab'da dene ve hatayı gör.",
      task: 'hostname -I ve hostname -f çalıştır, eth0 adresini submit et.', hint: '`hostname -I` ilk adres eth0. `hostname -f` FQDN.',
      solution: 'hostname -I\nhostname -f\nsubmit 192.168.1.42',
      check: (sh, c) => sySub(c, '192.168.1.42') },
    { id: 'sa3', title: 'Saat dilimi', xp: 20,
      story: "Log'lar CEST ile yazılıyor ama ekip İstanbul'da, cron saatleri kayıyor. timedatectl saat, dilim ve NTP durumunu gösterir, set-timezone ile dilimi değiştirir. Sistem geneli ayar olduğu için root ister, geçerli isimler list-timezones ile.",
      task: 'Saat dilimini Europe/Istanbul yap.', hint: '`timedatectl list-timezones | grep Istanbul` sonra `sudo timedatectl set-timezone Europe/Istanbul`.',
      solution: 'timedatectl\nsudo timedatectl set-timezone Europe/Istanbul\ntimedatectl',
      check: sh => syHas(sh, '/etc/timezone', 'Europe/Istanbul') },
    { id: 'sa4', title: 'Modül yükle', xp: 20,
      story: "USB diskin dosya sistemi vfat ve kernel modülü yüklü değil. lsmod yüklü modülleri listeler, modprobe bağımlılıklarıyla birlikte yükler, root ister. Yüklenince fat ve nls modülleri de gelir, lsmod bunu Used by sütununda gösterir.",
      task: 'vfat modülünü yükle ve lsmod ile yüklendiğini doğrula.', hint: '`sudo modprobe vfat` sonra `lsmod | grep vfat`.',
      solution: 'sudo modprobe vfat\nlsmod | grep vfat',
      check: sh => syHas(sh, '/proc/modules', 'vfat ') },
    { id: 'sa5', title: 'Modül kaldır', xp: 20,
      story: "rmmod bir modülü kaldırır ama başka modüller ona bağımlıysa in use der. ip_tables bunun örneği, iptable_filter onu kullanıyor. Bağımlılığı olmayan vfat kaldırılır. modprobe -r aynı işi bağımlılıklarıyla yapar.",
      task: 'Önce ip_tables modülünü kaldırmayı dene ve hatayı gör, sonra vfat modülünü kaldır.', hint: '`sudo rmmod ip_tables` in use der. `sudo rmmod vfat` çalışır.',
      solution: 'sudo rmmod ip_tables\nsudo rmmod vfat',
      check: sh => !syHas(sh, '/proc/modules', 'vfat ') && syHist(sh, /rmmod\s+ip_tables|modprobe\s+-r\s+ip_tables/) },
    { id: 'sa6', title: 'Açık dosya limiti', xp: 20,
      story: "nginx too many open files diyor. Her process'in açabileceği dosya sayısı sınırlı, ulimit -n bu shell'in soft limitini gösterir, ulimit -a hepsini. Soft limit hard limit'e kadar yükseltilebilir, daha fazlası root ister. Kalıcı ayar /etc/security/limits.conf içinde.",
      task: 'Açık dosya limitini gör ve bu shell için 4096 yap.', hint: '`ulimit -n` sonra `ulimit -n 4096`. `ulimit -n 9999999` dener misin, hard limit\'i aşamazsın.',
      solution: 'ulimit -n\nulimit -n 4096\nulimit -n',
      check: sh => syState(sh, 'nofile') === '4096' },
    { id: 'sa7', title: 'Planlı kapatma', xp: 25,
      story: "Disk bakımı için kutu 10 dakika sonra kapanacak, kullanıcılar uyarılsın. shutdown +10 mesaj hem planlar hem wall mesajı gönderir. Modern systemd'de shutdown tek başına poweroff demek, -h gerekmez. Vazgeçersen shutdown -c. Lab'da kutu gerçekten kapanmaz ama mesajlar gerçek.",
      task: 'Kutuyu 10 dakika sonraya mesajla planla, sonra iptal et.', hint: '`sudo shutdown +10 "disk bakimi"` sonra `sudo shutdown -c`.',
      solution: 'sudo shutdown +10 "disk bakimi"\nsudo shutdown -c',
      check: sh => !syEx(sh, '/run/systemd/shutdown/scheduled') && syHist(sh, /shutdown\s+\+10/) && syHist(sh, /shutdown\s+-c/) },
    { id: 'sa8', title: 'Bir kerelik iş', xp: 25,
      story: "cron tekrar eden işler için, bir kereliğine at kullanılır. Komutu stdin'den alır, zaman `now + 5 minutes`, `10:30` ya da `tomorrow` gibi. atq kuyruğu listeler, atrm siler. Lab'da zaman akmadığı için at-tick kuyruğu hemen çalıştırır.",
      task: "hello.sh script'ini 5 dakika sonraya planla, kuyruğu gör, sonra at-tick ile tetikle.", hint: '`echo "bash ~/scripts/hello.sh" | at now + 5 minutes`, `atq`, `at-tick`.',
      solution: 'echo "bash ~/scripts/hello.sh" | at now + 5 minutes\natq\nat-tick',
      check: (sh, c) => syRan(c, /^at-tick/) && c.out.includes('Merhaba') },
    { id: 'sa9', title: 'Canlı izle', xp: 15,
      story: "Disk dolarken df'yi tekrar tekrar yazmak yerine watch. watch -n 2 komut her iki saniyede bir ekranı yeniler, -d değişen yerleri vurgular, Ctrl+C ile çıkılır. Lab tek bir kare gösterir.",
      task: 'df -h komutunu watch ile iki saniye aralıkla izle.', hint: '`watch -n 2 df -h`.',
      solution: 'watch -n 2 df -h',
      check: (sh, c) => syRan(c, /^watch\b/) && c.out.includes('Every 2.0s') },
    { id: 'sa10', title: 'Kısayol dosya', xp: 20,
      story: "nginx access log'una her seferinde uzun yol yazmak yerine home'una bir symbolic link koy. ln -s hedef link, hedef önce gelir. ls -l link'i ok işaretiyle gösterir, cat link hedefi okur. -s olmadan hard link olur, aynı inode'un ikinci adı.",
      task: "/var/log/nginx/access.log için home directory'nde access.log adında symbolic link oluştur.", hint: '`ln -s /var/log/nginx/access.log ~/access.log` sonra `ls -l ~/access.log`.',
      solution: 'ln -s /var/log/nginx/access.log ~/access.log\nls -l ~/access.log',
      check: sh => { const n = sh.node(SY_H + '/access.log'); return !!n && n.l === '/var/log/nginx/access.log'; } },
  ],
});

CHAPTERS.push({
  id: 'remote', icon: '🔐', title: 'Uzak Erişim ve Transfer', sub: 'ssh, ssh-keygen, scp, rsync, sftp, gpg',
  missions: [
    { id: 'rm1', title: 'Uzakta komut', xp: 20,
      story: "Gece yedeklerini tutan backup.lab sunucusu var, ~/.ssh/known_hosts ve ~/.ssh/config içinde kayıtlı. ssh host komut biçimi komutu uzakta çalıştırıp çıktıyı getirir, interaktif oturum açmadan. Port farklıysa -p, kullanıcı farklıysa user@host.",
      task: "backup.lab üzerinde hostname komutunu çalıştır.", hint: '`ssh backup.lab hostname`. Şifre sorar, lab kabul eder. `ssh -p 2222 backup.lab` denersen refused alırsın, sshd 22\'de.',
      solution: 'ssh backup.lab hostname',
      check: (sh, c) => syRan(c, /^ssh\s+(\S+@)?backup(\.lab)?\s+hostname/) && c.out.includes('backup') },
    { id: 'rm2', title: 'Anahtar üret', xp: 20,
      story: "Her seferinde şifre yazmak hem yorucu hem güvensiz. ssh-keygen bir anahtar çifti üretir, private key sende kalır, public key sunuculara dağıtılır. Modern seçim ed25519, kısa ve hızlı. -C yorum alanı, hangi anahtar kimin anlamak için.",
      task: 'ed25519 tipinde, yorumu burak@linuxlab olan bir anahtar çifti üret.', hint: '`ssh-keygen -t ed25519 -C "burak@linuxlab"`. `ls -la ~/.ssh` ile id_ed25519 ve .pub dosyalarını gör.',
      solution: 'ssh-keygen -t ed25519 -C "burak@linuxlab"\nls -la ~/.ssh',
      check: sh => syHas(sh, SY_H + '/.ssh/id_ed25519.pub', 'ssh-ed25519') && syEx(sh, SY_H + '/.ssh/id_ed25519') },
    { id: 'rm3', title: 'Anahtarı dağıt', xp: 25,
      story: "ssh-copy-id public key'ini uzak sunucudaki ~/.ssh/authorized_keys dosyasına ekler, son kez şifre sorar. Elle yapmak istersen cat ~/.ssh/id_ed25519.pub çıktısını o dosyaya ekleyip 600 yaparsın.",
      task: "Public key'ini backup.lab sunucusuna kopyala.", hint: '`ssh-copy-id burak@backup.lab`. Sonra `ssh backup.lab cat .ssh/authorized_keys`.',
      solution: 'ssh-copy-id burak@backup.lab',
      check: sh => syHas(sh, syRemote + '/backup.lab/home/burak/.ssh/authorized_keys', 'ssh-ed25519') },
    { id: 'rm4', title: 'Şifresiz giriş', xp: 15,
      story: "Artık backup.lab şifre sormamalı. Deneyip gör, çıktıda password satırı yoksa publickey ile girdin demektir. Sunucu tarafında auth.log Accepted publickey yazar.",
      task: 'backup.lab üzerinde whoami çalıştır, şifre sorulmadığını gör.', hint: '`ssh backup.lab whoami`.',
      solution: 'ssh backup.lab whoami',
      check: (sh, c) => syRan(c, /^ssh\s+(\S+@)?backup(\.lab)?\s+whoami/) && c.out.trim() === 'burak' },
    { id: 'rm5', title: 'Dosya gönder', xp: 20,
      story: "scp cp gibi çalışır, bir taraf `user@host:yol` biçiminde. Notlarını yedek sunucusuna at. İki nokta önemli, unutursan scp yerel bir dosyaya kopyalar.",
      task: "notes.txt dosyasını backup.lab sunucusundaki /var/backups dizinine kopyala.", hint: '`scp ~/notes.txt backup.lab:/var/backups/` sonra `ssh backup.lab ls /var/backups`.',
      solution: 'scp ~/notes.txt backup.lab:/var/backups/\nssh backup.lab ls /var/backups',
      check: sh => syEx(sh, syRemote + '/backup.lab/var/backups/notes.txt') },
    { id: 'rm6', title: 'Yedeği geri al', xp: 25,
      story: "Ters yön aynı mantık, kaynak uzakta hedef yerelde. Eski yedek notes-2026-10-01.tar.gz backup.lab üzerinde. İndir, açmadan önce tar tzf ile içine bak.",
      task: '/var/backups/notes-2026-10-01.tar.gz dosyasını /tmp altına indir ve içeriğini listele.', hint: '`scp backup.lab:/var/backups/notes-2026-10-01.tar.gz /tmp/` sonra `tar tzf /tmp/notes-2026-10-01.tar.gz`.',
      solution: 'scp backup.lab:/var/backups/notes-2026-10-01.tar.gz /tmp/\ntar tzf /tmp/notes-2026-10-01.tar.gz',
      check: (sh, c) => syEx(sh, '/tmp/notes-2026-10-01.tar.gz') && syRan(c, /tar\s+-?t/) },
    { id: 'rm7', title: 'Dizin gönder', xp: 20,
      story: "web01.lab yeni web sunucusu. webapp dizinini oraya taşıyacaksın, dizin için -r. ~ hedefin home'u demek, `scp -r dizin host:~/` yazınca uzakta home altına düşer.",
      task: "~/projects/webapp dizinini web01.lab sunucusundaki home directory'ne kopyala.", hint: '`scp -r ~/projects/webapp web01.lab:~/` sonra `ssh web01.lab ls webapp`.',
      solution: 'scp -r ~/projects/webapp web01.lab:~/\nssh web01.lab ls webapp',
      check: sh => syEx(sh, syRemote + '/web01.lab/home/burak/webapp/app.py') },
    { id: 'rm8', title: 'rsync ile deploy', xp: 30,
      story: "Her deploy'da tüm dizini scp ile atmak israf, rsync sadece değişenleri gönderir. -a izin ve zamanları korur, -v listeler, -z sıkıştırır. --delete hedefte artık olmayan dosyaları siler, bu yüzden önce -n ile dry run yapılır. Kaynak sonundaki / içeriği gönderir, / yoksa dizinin kendisini.",
      task: "webapp içeriğini web01.lab üzerindeki /var/www/html dizinine --delete ile senkronla, önce dry run.", hint: '`rsync -avn --delete ~/projects/webapp/ web01.lab:/var/www/html/` sonra -n olmadan aynısı.',
      solution: 'rsync -avn --delete ~/projects/webapp/ web01.lab:/var/www/html/\nrsync -av --delete ~/projects/webapp/ web01.lab:/var/www/html/',
      check: sh => syEx(sh, syRemote + '/web01.lab/var/www/html/app.py') && !syEx(sh, syRemote + '/web01.lab/var/www/html/index.html') && syHist(sh, /rsync\s+-\w*n/) },
    { id: 'rm9', title: 'sftp', xp: 20,
      story: "sftp ssh üzerinden interaktif dosya transferi. sftp user@host yazınca sftp> promptu açılır, orada get indirir, put yükler, ls ve cd gezer, quit çıkar. Bunlar sftp oturum komutlarıdır, bash'te get yazarsan command not found alırsın. Lab'da prompt yok, tek satır biçimi `sftp host:dosya` indirir.",
      task: "backup.lab üzerindeki /var/backups/README dosyasını sftp ile home directory'ne indir.", hint: '`cd ~` sonra `sftp backup.lab:/var/backups/README`.',
      solution: 'cd ~\nsftp backup.lab:/var/backups/README',
      check: (sh, c) => syEx(sh, SY_H + '/README') && syRan(c, /^sftp\b/) },
    { id: 'rm10', title: 'Şifreli yedek', xp: 30,
      story: "Raporu yedek sunucusuna göndereceksin ama orada düz metin durmasın. gpg -c simetrik şifreler, aynı passphrase ile açılır, dosya.gpg üretir. Gerçek gpg passphrase'i pencereden sorar, lab'da --batch --passphrase ile verilir. Gönderdikten sonra yerel şifreli kopyayı shred -u ile diskten kazı, rm sadece referansı siler.",
      task: 'rapor.txt dosyasını gpg ile şifrele, .gpg dosyasını backup.lab /var/backups altına gönder, sonra yerel .gpg dosyasını shred ile yok et.', hint: '`gpg --batch --passphrase lab123 -c ~/Documents/rapor.txt`, `scp ~/Documents/rapor.txt.gpg backup.lab:/var/backups/`, `shred -u ~/Documents/rapor.txt.gpg`.',
      solution: 'gpg --batch --passphrase lab123 -c ~/Documents/rapor.txt\nscp ~/Documents/rapor.txt.gpg backup.lab:/var/backups/\nshred -u ~/Documents/rapor.txt.gpg',
      check: sh => syEx(sh, syRemote + '/backup.lab/var/backups/rapor.txt.gpg') && !syEx(sh, SY_H + '/Documents/rapor.txt.gpg') && syHist(sh, /^shred\b/) },
  ],
});

CHAPTERS.push({
  id: 'jobs', icon: '⚙️', title: 'Job Kontrolü ve Öncelik', sub: '&, jobs, fg, bg, nohup, nice, renice, trap',
  missions: [
    { id: 'jb1', title: 'Arkaya at', xp: 15,
      story: "Uzun süren bir komut terminali kilitler. Sonuna & koyarsan arka planda çalışır, shell hemen prompt verir ve job numarasıyla PID yazar. jobs bu shell'in arka plan işlerini listeler, -l ile PID de görünür, aynı process ps çıktısında da var. Job numarası shell'e özel, PID sistem geneli.",
      task: 'sleep 300 komutunu arka planda başlat, sonra jobs -l ile job listesini PID ile gör.', hint: '`sleep 300 &` sonra `jobs -l`. Köşeli parantezdeki 1 job numarası, yanındaki PID. `ps` aynı PID\'yi gösterir.',
      solution: 'sleep 300 &\njobs -l\nps',
      check: (sh, c) => !!syJob(sh, 'sleep 300') && syRan(c, /^jobs\b/) && c.out.includes('Running') },
    { id: 'jb3', title: 'Durdur, sürdür', xp: 25,
      story: "Gerçek terminalde Ctrl+Z öndeki komutu durdurur, bg arka planda sürdürür, fg öne alır. Lab'da Ctrl+Z yok, aynı etkiyi kill -STOP %1 verir. %1 job adresleme, kill, fg ve bg hepsinde geçerli.",
      task: "1 numaralı job'ı durdur, jobs ile Stopped gör, sonra bg ile arkada sürdür.", hint: '`kill -STOP %1`, `jobs`, `bg %1`.',
      solution: 'kill -STOP %1\njobs\nbg %1',
      check: sh => { const j = syJob(sh, 'sleep 300'); return !!j && (j.st || 'Running') === 'Running' && syHist(sh, /kill\s+-STOP/); } },
    { id: 'jb4', title: 'Öne al', xp: 15,
      story: "fg job'ı öne alır, terminal ona kilitlenir, bitince prompt döner. Gerçek hayatta sleep 300 için beş dakika beklersin ya da Ctrl+C ile kesersin, lab job'ı bitmiş sayar.",
      task: "sleep 300 job'ını öne al.", hint: '`fg %1` ya da tek job varsa `fg`.',
      solution: 'fg %1',
      check: (sh, c) => !syJob(sh, 'sleep 300') && syRan(c, /^fg\b/) },
    { id: 'jb5', title: 'nohup', xp: 25,
      story: "Arka plan job'ı terminal kapanınca SIGHUP alıp ölür. nohup komut & bu signal'i yok sayar ve çıktıyı nohup.out dosyasına yazar. Modern alternatifler tmux ya da systemd-run, ama nohup her yerde var.",
      task: "hello.sh script'ini nohup ile arka planda çalıştır ve nohup.out dosyasını oku.", hint: '`cd ~`, `nohup bash ~/scripts/hello.sh &`, `cat nohup.out`.',
      solution: 'cd ~\nnohup bash ~/scripts/hello.sh &\ncat nohup.out',
      check: sh => syHas(sh, SY_H + '/nohup.out', 'Merhaba') },
    { id: 'jb6', title: 'Düşük öncelik', xp: 25,
      story: "Büyük bir arşivleme işi sistemi yavaşlatmasın. nice -n 10 komut, niceness 10 ile başlatır. Niceness 19 en düşük öncelik, -20 en yüksek, negatif değer root ister. ps -o pid,ni,cmd ile görürsün. $! son arka plan PID'si.",
      task: 'sleep 500 komutunu niceness 10 ile arka planda başlat ve ps ile NI sütununu gör.', hint: '`nice -n 10 sleep 500 &` sonra `ps -o pid,ni,cmd -p $!`.',
      solution: 'nice -n 10 sleep 500 &\nps -o pid,ni,cmd -p $!',
      check: sh => { const j = syJob(sh, 'sleep 500'); return !!j && j.ni === 10; } },
    { id: 'jb7', title: 'renice', xp: 25,
      story: "Çalışan bir process'in önceliğini renice değiştirir, renice -n 15 -p PID. Sıradan kullanıcı niceness'ı sadece artırabilir yani önceliği düşürebilir, geri almak root ister. Bu yüzden 10'dan 15'e çıkar ama 5'e inemezsin.",
      task: "sleep 500 process'inin niceness değerini 15 yap.", hint: '`renice -n 15 -p $!`. PID\'yi `pgrep sleep` ya da `jobs -l` ile de bulursun.',
      solution: 'renice -n 15 -p $!',
      check: sh => { const j = syJob(sh, 'sleep 500'); return !!j && j.ni === 15; } },
    { id: 'jb8', title: 'İsimle öldür', xp: 15,
      story: "PID aramak yerine isimle kill. killall isim tam ad eşleşmesi ister, pkill isim kısmi eşleşir. İkisi de default SIGTERM gönderir, inatçı process için -9.",
      task: "Tüm sleep process'lerini isimle öldür.", hint: '`killall sleep` ya da `pkill sleep`. `jobs` boş dönmeli.',
      solution: 'killall sleep\njobs',
      check: (sh, c) => !sh.procs.some(p => p.cmd.startsWith('sleep')) && syHist(sh, /^(killall|pkill)\s+sleep/) },
    { id: 'jb9', title: 'Ağaç ve bellek', xp: 20,
      story: "pstree process'leri parent child ağacı olarak gösterir, -p ile PID. Kim kimi başlatmış, bir servisin alt process'leri neler, tek bakışta. pmap PID bir process'in bellek haritasını verir, hangi kütüphane ne kadar yer tutuyor, en altta total.",
      task: "pstree -p ile ağaca bak, sonra 1024 numaralı process'in bellek haritasının toplam satırını göster.", hint: '`pstree -p` sonra `pmap 1024 | tail -1`.',
      solution: 'pstree -p\npmap 1024 | tail -1',
      check: (sh, c) => syHist(sh, /^pstree/) && syRan(c, /^pmap\b/) && c.out.includes('total') },
    { id: 'jb10', title: 'trap ile temizlik', xp: 35,
      story: "Script geçici dosya açıyor, hata olsa da bitince silinmeli. trap 'komut' EXIT script çıkarken komutu çalıştırır, Ctrl+C için INT. trap interaktif satırda da kabul edilir ama asıl yeri script. $$ script'in PID'si, geçici dosya adı için klasik.",
      task: "nano ile ~/scripts/cleanup.sh yaz. /tmp/work.$$ dosyası oluştursun, EXIT trap'i dosyayı silip temizlendi yazsın. Çalıştır.", hint: 'TMP=/tmp/work.$$ sonra trap "rm -f $TMP; echo temizlendi" EXIT, sonra touch $TMP ve echo calisiyor.',
      solution: 'nano ~/scripts/cleanup.sh\nbash ~/scripts/cleanup.sh',
      editorContent: '#!/bin/bash\nTMP=/tmp/work.$$\ntrap "rm -f $TMP; echo temizlendi" EXIT\ntouch $TMP\necho calisiyor\n',
      check: (sh, c) => syHas(sh, SY_H + '/scripts/cleanup.sh', 'trap') && c.out.includes('temizlendi') },
  ],
});

CHAPTERS.push({
  id: 'cheat', icon: '🧐', title: "Cheat sheet'i doğrula", sub: "Mousepad'de yanlış ya da eskimiş ne varsa",
  missions: [
    { id: 'cs1', title: 'source ne değildir', xp: 25,
      story: "Mousepad diyor ki source dosya, compile from source code. Yanlış. source bir dosyayı mevcut shell içinde çalıştırır, içindeki değişkenler ve fonksiyonlar shell'de kalır, . dosya aynı şey. Kaynaktan derleme ./configure && make && sudo make install, onu Paket bölümünde yaptın.",
      task: "~/scripts/vars.sh dosyasını source et ve echo ile APP değişkenini yazdır.", hint: '`source ~/scripts/vars.sh` sonra `echo $APP`. `bash vars.sh` ile çalıştırsan değişken sende kalmazdı.',
      setup: sh => { sh.writeFile(SY_H + '/scripts/vars.sh', 'export APP=linuxlab\nAPP_PORT=8080\n', false, 'nano'); },
      solution: 'source ~/scripts/vars.sh\necho $APP',
      check: sh => sh.env.APP === 'linuxlab' && syHist(sh, /^(source|\.)\s+\S*vars\.sh/) },
    { id: 'cs2', title: 'net-tools eskidi', xp: 25,
      story: "Mousepad ifconfig ve netstat -pnltu diyor. İkisi de net-tools paketinden, 2009'dan beri deprecated, yeni kurulumlarda yok. Modern karşılıkları ip addr ve ss -tulpn. Lab'da eskileri çalıştır, uyarıyı oku, sonra yenileriyle aynı bilgiyi al.",
      task: 'ifconfig ve netstat -tulpn çalıştır, sonra aynı bilgiyi ip -br addr ve ss -tulpn ile al.', hint: '`ifconfig`, `netstat -tulpn`, `ip -br addr`, `ss -tulpn`.',
      solution: 'ifconfig\nnetstat -tulpn\nip -br addr\nss -tulpn',
      check: (sh, c) => syRan(c, /^ss\s+-\w*[tul]/) && syHist(sh, /^ifconfig/) && syHist(sh, /^netstat/) && syHist(sh, /^ip\s+(-br\s+)?a/) },
    { id: 'cs3', title: 'get ve put', xp: 20,
      story: "Mousepad get, put ve quit'i Linux komutu gibi listelemiş. Değiller. Bunlar sftp ve ftp oturumunun içinde çalışır, sftp> promptunda. Bash'te get yazarsan command not found. Tek satırlık karşılıkları scp.",
      task: "Bash'te get README yaz ve hatayı gör, sonra aynı dosyayı backup.lab'dan /tmp altına scp ile indir.", hint: '`get README` sonra `scp backup.lab:/var/backups/README /tmp/`.',
      solution: 'get README\nscp backup.lab:/var/backups/README /tmp/',
      check: sh => syEx(sh, '/tmp/README') && syHist(sh, /^get\s/) },
    { id: 'cs4', title: 'ip address add eksik', xp: 25,
      story: "Mousepad ip address add ip yazmış. Eksik. Kernel adresi hangi interface'e ekleyeceğini bilmeli, dev zorunlu, prefix yoksa /32 olur ve subnet route oluşmaz. Doğrusu sudo ip addr add 10.0.0.5/24 dev eth1. Root ister.",
      task: "Mousepad'deki haliyle dene, hatayı oku, sonra 10.0.0.5/24 adresini eth1 üzerine doğru biçimde ekle.", hint: '`sudo ip addr add 10.0.0.5` hata verir. `sudo ip addr add 10.0.0.5/24 dev eth1` sonra `ip addr show eth1`.',
      solution: 'sudo ip addr add 10.0.0.5\nsudo ip addr add 10.0.0.5/24 dev eth1\nip addr show eth1',
      check: sh => syState(sh, 'extra').includes('10.0.0.5/24@eth1') },
    { id: 'cs5', title: '766 tuhaf', xp: 20,
      story: "Mousepad chmod 766 diyor. Teknik olarak geçerli ama tuhaf, group ve others yazabilir ama çalıştıramaz, dizinde x olmadan içine girilemez. Gerçek hayatta görülen kalıplar 755 script ve dizin, 644 düz dosya, 600 gizli dosya, 700 gizli dizin. 777 bir çözüm değil, bir itiraf.",
      task: "~/lab/deploy.sh dosyasına önce 766 ver, lab'ın notunu oku, sonra 755 yap.", hint: '`chmod 766 ~/lab/deploy.sh` sonra `chmod 755 ~/lab/deploy.sh`. `ls -l` ile rwxr-xr-x gör.',
      setup: sh => { if (!syEx(sh, SY_H + '/lab')) sh.run('mkdir -p ~/lab'); sh.writeFile(SY_H + '/lab/deploy.sh', '#!/bin/bash\necho deploy\n', false, 'nano'); },
      solution: 'chmod 766 ~/lab/deploy.sh\nchmod 755 ~/lab/deploy.sh\nls -l ~/lab/deploy.sh',
      check: sh => { const n = sh.node(SY_H + '/lab/deploy.sh'); return !!n && (n.m & 0o777) === 0o755 && syHist(sh, /chmod\s+766/); } },
    { id: 'cs6', title: 'shutdown saati', xp: 20,
      story: "Mousepad `shutdown hh:mm` diyor, eski sistemlerde bu tek başına çalışmaz, -h ya da -r gerekirdi. Modern systemd shutdown default olarak poweroff yapar, `shutdown 23:30` yeter, `shutdown -r +5` yeniden başlatır, `shutdown -c` iptal eder. -h hâlâ kabul edilir ama gerekmez.",
      task: 'Kutuyu `23:30` saatine planla, sonra iptal et.', hint: '`sudo shutdown 23:30` sonra `sudo shutdown -c`.',
      solution: 'sudo shutdown 23:30\nsudo shutdown -c',
      check: sh => syHist(sh, /shutdown\s+(-h\s+)?\d{1,2}:\d{2}/) && !syEx(sh, '/run/systemd/shutdown/scheduled') && syHist(sh, /shutdown\s+-c/) },
    { id: 'cs7', title: 'Kısayollar', xp: 25,
      story: "Mousepad'in bash kısayolları karışık. Ctrl+G geçmişten çıkmaz, sadece aramayı iptal eder. Ctrl+O bulunan komutu çalıştırıp sıradakini getirir, günlük işte kullanılmaz. Ctrl+Q uygulamadan çıkmaz, Ctrl+S ile donan ekranı sürdürür. Gerçek liste, Ctrl+C durdur, Ctrl+Z askıya al, Ctrl+D çık, Ctrl+L temizle, Ctrl+R geçmişte ara, Ctrl+A satır başı, Ctrl+E satır sonu, Ctrl+U başa kadar sil, Ctrl+K sona kadar sil, Ctrl+W kelime sil, Ctrl+Y yapıştır, Alt+. son argüman, !! son komut, !$ son argüman.",
      task: 'Komut geçmişinde geriye doğru arama yapan kısayolu submit et.', hint: 'Ters arama, reverse search. Ctrl ile bir harf, submit Ctrl+R biçiminde.',
      solution: 'submit Ctrl+R',
      check: (sh, c) => sySub(c, 'ctrl+r', 'ctrl r', 'ctrl-r', '^r', 'c-r', 'control+r', 'ctrl+r reverse search') },
    { id: 'cs8', title: 'finger yok', xp: 20,
      story: "Mousepad finger diyor. Çoğu sunucuda kurulu değil, bu kutuda da yok. Kullanıcı bilgisi için standart araçlar id, getent passwd isim, w ve last. İstersen apt ile kurulur ama alışkanlık olarak id ve getent öğren.",
      task: 'finger burak dene, hatayı gör, sonra id ve getent passwd ile aynı bilgiyi al.', hint: '`finger burak`, `id burak`, `getent passwd burak`.',
      solution: 'finger burak\nid burak\ngetent passwd burak',
      check: (sh, c) => syRan(c, /getent\s+passwd\s+burak/) && syHist(sh, /^finger/) },
    { id: 'cs9', title: 'Büyük i', xp: 15,
      story: "Mousepad hostname -l yazmış. Öyle bir seçenek yok, hostname hata verir. IP adresleri için büyük i, hostname -I. Küçük i -i hostname'e karşılık gelen tek adresi verir, genelde 127.0.1.1.",
      task: 'hostname -l dene, hatayı gör, sonra hostname -I ile adresleri al.', hint: '`hostname -l` sonra `hostname -I`.',
      solution: 'hostname -l\nhostname -I',
      check: (sh, c) => syRan(c, /hostname\s+-I/) && syHist(sh, /hostname\s+-l/) },
    { id: 'cs10', title: 'ls | xargs wc', xp: 25,
      story: "Mousepad ls | xargs wc diyor, dizin boyutu sanmak kolay ama bu dizindeki dosyaların içeriğini sayar, dizini değil. Üstelik boşluklu ad içeren dosyada kırılır, xargs boşluktan böler. Doğrusu wc *, ya da güvenli hali find . -type f -print0 | xargs -0 wc.",
      task: "~/lab/wc dizininde ls | xargs wc çalıştır ve hatayı gör, sonra wc * ile doğru sonucu al.", hint: '`cd ~/lab/wc`, `ls | xargs wc`, `wc *`.',
      setup: sh => { sh.run('mkdir -p ~/lab/wc'); sh.writeFile(SY_H + '/lab/wc/a.txt', 'bir\niki\n', false, 'nano'); sh.writeFile(SY_H + '/lab/wc/b c.txt', 'uc\n', false, 'nano'); },
      solution: 'cd ~/lab/wc\nls | xargs wc\nwc *',
      check: (sh, c) => syRan(c, /^wc\s+\*|find\b.*-print0\s*\|\s*xargs\s+-0/) && syHist(sh, /ls\s*\|\s*xargs\s+wc/) },
    { id: 'cs11', title: 'locate boş döner', xp: 25,
      story: "Mousepad locate dosya diyor ama locate tek başına çalışmaz. mlocate paketi gerekir, sonra veritabanını sudo updatedb üretmeli. locate diskte aramaz, bu veritabanına bakar, bu yüzden find'dan çok hızlı ama yeni dosyaları updatedb çalışana kadar bilmez.",
      task: "locate ile sshd_config dosyasını bul. Önce komut yok, sonra veritabanı yok hatalarını gör ve düzelt.", hint: '`locate sshd_config`, `sudo apt install mlocate`, `sudo updatedb`, `locate sshd_config`.',
      solution: 'locate sshd_config\nsudo apt install mlocate\nsudo updatedb\nlocate sshd_config',
      check: (sh, c) => syRan(c, /^locate\b/) && c.out.includes('/etc/ssh/sshd_config') },
    { id: 'cs12', title: 'Tek boşluk', xp: 25,
      story: "Mousepad'de rm -rf var, uyarı yok. rm -rf /tmp/x/ yazarken parmak kayar, rm -rf /tmp/x / olur, ikinci argüman kök dizin. Gerçek rm bunu preserve-root ile durdurur, --no-preserve-root dersen durdurmaz. Değişkenli yollarda `rm -rf \"$DIR\"/x` yerine `rm -rf \"${DIR:?}\"/x` yaz, DIR boşsa komut patlar, silmez. Lab'da güvenle dene, gerçek sistemde asla.",
      task: 'rm -rf /tmp/x / komutunu çalıştır ve korumanın mesajını oku.', hint: 'Komutu aynen yaz. Lab durdurur ve gerçek sistemin mesajını gösterir.',
      solution: 'rm -rf /tmp/x /',
      check: (sh, c) => syRan(c, /^rm\s+-rf\s+\S+\s+\/\s*$/) && syEx(sh, '/etc', 'd') },
  ],
});

